CREATE OR REPLACE FUNCTION public.amora_today_one_presentation_is_valid(p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_kind text;
  v_next_action jsonb;
  v_choices jsonb;
  v_href text;
