DECLARE
  v_hour integer := extract(hour FROM (public.amora_push_clock() AT TIME ZONE 'Asia/Seoul'))::integer;
  v_start integer := 9;
  v_end integer := 20;
BEGIN
  SELECT greatest(9, coalesce(profile.care_window_start_hour, 9)),
         least(20, coalesce(profile.care_window_end_hour, 20))
  INTO v_start, v_end
  FROM public.profiles AS profile
  WHERE profile.id = p_user_id;
  RETURN v_start < v_end AND v_hour >= v_start AND v_hour < v_end;
END

DECLARE
  v_cadence jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('amora_care_daily_cap:' || p_couple_id::text, 0)
  );
  v_cadence := public.amora_care_couple_cadence(p_couple_id);
  IF v_cadence->>'intensity' = 'light'
     AND NOT public.amora_care_is_imminent(COALESCE(p_metadata, '{}'::jsonb)) THEN
    RETURN 'intensity_filtered';
  END IF;
  IF public.amora_care_posts_on_kst_day(p_couple_id, now())
       >= (v_cadence->>'daily_limit')::integer THEN
    RETURN 'daily_care_limit';
  END IF;
  RETURN 'allowed';
END

